#[test]fn sqlite_snapshot_en1997_all_fifty_five_fields_have_independent_exact_word_oracle(){use std::io::Write;use std::process::{Command,Stdio};let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true});const expected=BigInt.asIntN(64,BigInt('0x'+process.env.SEMIO_TEST_WORD));let count=0;for(const t of d.query(\"SELECT name FROM sqlite_schema WHERE type='table'\").all()){for(const c of d.query('PRAGMA table_info('+t.name+')').all()){if(!c.name.endsWith('_ieee754_bits'))continue;for(const v of d.query('SELECT '+c.name+' AS value FROM '+t.name).all()){if(v.value!==expected)throw Error('independent bit identity');count++;}}}if(count!==55)throw Error('all55scalars');await Bun.write(Bun.stdout,d.serialize());d.close();";for word in f["binary64Words"].as_array().unwrap(){let word=word.as_str().unwrap();let s=every_word(u64::from_str_radix(word,16).unwrap());let d=project(&s);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let mut child=Command::new("bun").args(["-e",script]).env("SEMIO_TEST_WORD",word).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let restored=restore(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(project(&restored),d);}}
#[test]fn sqlite_snapshot_en1997_every_ieee_word_survives_actual_erased_native_encodings(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let p=store::ArtifactCodec::bare::<En1997Snapshot,crate::En1997Mutation>(crate::EN1997_DOCUMENT_SCHEMA).snapshot_sqlite.unwrap();let dialect=store::io_schema::ArtifactDialect{artifact_kind:"s.norm.en1997".into(),standard:"1".into(),subset:"*".into()};for word in f["binary64Words"].as_array().unwrap(){let s=every_word(u64::from_str_radix(word.as_str().unwrap(),16).unwrap());let expected=project(&s);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(<En1997Snapshot as store::ArtifactPack>::encode_pack(&s)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(<En1997Snapshot as store::ArtifactDsl>::print_dsl(&s))};let d=(p.export)(crate::EN1997_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(project(&restore(&d).unwrap()),expected);let back=(p.import)(crate::EN1997_DOCUMENT_SCHEMA,&dialect,d,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(back,payload);}}}
#[test]fn sqlite_snapshot_en1997_controlled_native_owner_admits_physical_and_typed_state(){let s=fixture();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(<En1997Snapshot as store::ArtifactPack>::encode_pack(&s)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(<En1997Snapshot as store::ArtifactDsl>::print_dsl(&s))};let back=En1997Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(project(&back),project(&s));assert!(En1997Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(En1997Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:16,..SqliteDatabaseLimits::default()})).is_err());}}

#[test]
fn sqlite_snapshot_en1997_controlled_output_has_exact_wire_and_real_interior_admission(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let limits=&corpus["controlledOutput"];let count=limits["textBytes"].as_u64().unwrap() as usize;let after=limits["cancelAfter"].as_u64().unwrap() as usize;let tiny=limits["tinyBytes"].as_u64().unwrap() as usize;let mut s=fixture();s.structure_id="x".repeat(count);let rows=project(&s).tables.iter().map(|table|table.rows.len()).sum();
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let expected=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(<En1997Snapshot as store::ArtifactPack>::encode_pack(&s)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(<En1997Snapshot as store::ArtifactDsl>::print_dsl(&s))};let actual=s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert!(actual==expected,"controlled owner wire differs");let bytes=match &expected{store::io_schema::IoPayload::Binary(v)=>v.len(),store::io_schema::IoPayload::Text(v)=>v.len()};assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:bytes,..SqliteDatabaseLimits::default()})).unwrap()==expected);let mut interior=false;let error=s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |event|{let stop=event.phase==SqliteSnapshotPhase::EncodeNative&&event.total>after&&event.completed>=after&&event.completed<event.total;interior|=stop;!stop},SqliteDatabaseLimits::default())).unwrap_err();assert!(interior&&error.kind == semio_framework_value::ValueRefusalKind::Canceled,"{error}");assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:rows,..SqliteDatabaseLimits::default()})).unwrap()==expected);for budget in[SqliteDatabaseLimits{max_rows:rows-1,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_file_bytes:bytes-1,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_value_bytes:tiny,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_rows:0,..SqliteDatabaseLimits::default()}]{assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,budget)).is_err());}assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
}

